#pragma once#include <UniBufferT.h>#include <macros/csvrow.h>#include <FSC_Info.h>namespace ns_details{  namespace ns_UC  {    struct SLocal     {      UINT m_nSize;      UINT m_nName;     };  }  struct SUniCols : public SUniBufferT<ns_UC::SLocal>  {    SUniCols(SUniNameT& n)      : SUniBufferT(), name(n){};    //    SUniNameT& name;    const char* Name(int n)    {      ns_UC::SLocal* lst = (ns_UC::SLocal*)m_szBuffer;      return name.Name(lst[n].m_nName);    }    //    void Add( SFormatHdr* hdr )    {      if ( !Realloc(1) )        return;      int n = AddCurr();      ns_UC::SLocal* lst = (ns_UC::SLocal*)m_szBuffer;      lst[n].m_nName = name.Add( hdr->name );    }  };  //  namespace ns_UD  {    struct SLocal     {      UINT N[42];     };  }  struct SUniData : public SUniBufferT<ns_UD::SLocal>  {    SUniData(SUniNameT& n)      : SUniBufferT(), name(n)    {    }    //    SUniNameT& name;    const char* Name(int n,int m)    {      ns_UD::SLocal* lst = m_szBuffer;      if( !lst )        return '\0';      return name.Name( lst[n].N[m] );    }    //    UINT TAGNUMBER(int n)    {      ns_UD::SLocal* lst = (ns_UD::SLocal*)m_szBuffer;      return lst[n].N[1];    }    //    void Add( UINT n, UINT m, char* ptr )    {      ns_UD::SLocal* lst = (ns_UD::SLocal*)m_szBuffer;      lst[n].N[m] = name.Add( ptr );    }  };}class CDbfFiles{public:  ns_details::SUniData mData;  ns_details::SUniCols mCols;  SUniNameT mName;  SUniCharT mChar;public:  CDbfFiles();  ~CDbfFiles();  bool BuildList( LPCSTR pszCsv, LPCSTR pszBin );  int  FindTag( const char* ptr );protected:  void LoadCols( aCSVRow_ &row );  void LoadData( aCSVRow_ &row, std::istream &file );};